window.createVocabularyLibrary = function ({ getState, words, esc, details, save, toast, home, resume, stopTimer }) {
  const $ = s => document.querySelector(s);
  const normalize = text => text.trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ');
  const samples = [
    {id:'look-forward-to',text:'look forward to',meaning:'期待；盼望',sentence:'I look forward to seeing you again.',translation:'我期待再次见到你。'},
    {id:'make-progress',text:'make progress',meaning:'取得进步',sentence:'Regular practice helps you make steady progress.',translation:'经常练习有助于你稳步进步。'},
    {id:'in-other-words',text:'in other words',meaning:'换句话说',sentence:'The room is quiet. In other words, it is a good place to study.',translation:'房间很安静。换句话说，这里适合学习。'}
  ];
  const filters={words:{q:'',status:'all'},phrases:{q:'',status:'all'}};
  let drawerReturn, editId=null;
  function ensureState(){
    const s=getState();s.libraryTab ??= 'learn';s.enrolled ??= Object.keys(s.mastery);s.wordSources ??= {};
    for(const id of s.notebook)if(!s.wordSources[id])s.wordSources[id]=[{label:'收藏原句示例 · 非真实文章记录',sentence:words[id].examples[0]?.text||'',translation:words[id].examples[0]?.translationZh||''}];
    s.phrases ??= samples.map(p=>({...p,saved:true,enrolled:false,note:'',sources:[{label:'原创词组示例 · 非真实文章记录',sentence:p.sentence,translation:p.translation}]}));
    s.phraseEvents ??= [];s.phraseRound ??= null;
  }
  function frame(){const s=getState();return `<div class="heading"><div><h1>背单词</h1><p class="muted">遇见、收藏，再一点点记牢。</p></div><button class="secondary" id="history-open">学习记录 ↗</button></div><nav class="vocabulary-tabs" aria-label="词汇模块"><button data-tab="learn" ${s.libraryTab==='learn'?'aria-current="page"':''}>今日学习</button><button data-tab="words" ${s.libraryTab==='words'?'aria-current="page"':''}>生词本 <small>${s.notebook.length}</small></button><button data-tab="phrases" ${s.libraryTab==='phrases'?'aria-current="page"':''}>词组本 <small>${s.phrases.filter(p=>p.saved).length}</small></button></nav>`;}
  function bindTabs(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{getState().libraryTab=b.dataset.tab;save();home();});}
  function enrolled(id){const s=getState();return s.enrolled.includes(id)||!!s.mastery[id];}
  function wordStatus(id){const s=getState();return s.exempt[id]?'熟练 · 免复习':!enrolled(id)?'未加入学习':!s.mastery[id]?'待新学':s.mastery[id].due<=Date.now()?'已到期':'学习中';}
  function pending(){const r=getState().round;return r && r.phase!=='COMPLETED'?'<div class="library-resume"><span>学习已暂停，输入和原队列已保存。</span><button id="resume" class="text-button">返回这轮学习 →</button></div>':'';}
  function render(){
    ensureState();const s=getState(),kind=s.libraryTab,f=filters[kind];
    $('#app').innerHTML=frame()+pending()+(kind==='phrases'&&s.phraseRound&&s.phraseRound.phase!=='DONE'?'<div class="library-resume"><span>还有一个未完成的词组练习，已保存输入和辅助记录。</span><button id="resume-phrase" class="text-button">继续词组练习 →</button></div>':'')+`<section class="library-content"><div class="library-intro"><div><h2>${kind==='words'?'把有用的词，留在这里。':'让单词连起来，记住它的用法。'}</h2><p class="muted">${kind==='words'?'收藏与学习分别管理，原句和出处一起保留。':'词组独立收藏、独立练习，不计入单词新学额度。'}</p></div>${kind==='phrases'?'<button class="primary" id="add-phrase">＋ 收藏词组</button>':'<button class="secondary" id="personal-study">从生词本开始学习 →</button>'}</div><div class="library-toolbar"><label class="library-search"><span aria-hidden="true">⌕</span><input id="library-search" type="search" placeholder="${kind==='words'?'搜索单词或中文释义':'搜索词组或中文释义'}" aria-label="搜索收藏" value="${esc(f.q)}"></label><select id="library-filter" aria-label="筛选学习状态"><option value="all">全部状态</option><option value="unjoined">未加入学习</option><option value="joined">已加入学习</option>${kind==='words'?'<option value="exempt">熟练免复习</option>':''}</select></div><div id="library-list"></div><p class="library-boundary">${kind==='words'?'本地演示收藏 · 正式站点历史收藏与多来源记录未接入此原型。':'词组功能演示 · 原创示例与个人输入，仅存在本浏览器。'} <a id="legacy-notebook" href="#notebook">原笔记本入口</a> · <a href="http://127.0.0.1:4174/notebook" target="_blank" rel="noopener">打开正式笔记本 ↗</a></p></section>`;
    bindTabs();$('#history-open').onclick=()=>document.dispatchEvent(new Event('prototype-history'));
    $('#resume')?.addEventListener('click',resume);$('#resume-phrase')?.addEventListener('click',()=>openPractice(s.phraseRound.id));
    $('#legacy-notebook').onclick=e=>{e.preventDefault();s.libraryTab='words';save();home();};
    $('#library-search').oninput=e=>{f.q=e.target.value;renderRows();};$('#library-filter').value=f.status;$('#library-filter').onchange=e=>{f.status=e.target.value;renderRows();};
    $('#add-phrase')?.addEventListener('click',()=>openEditor());
    $('#personal-study')?.addEventListener('click',()=>{s.book='personal';s.libraryTab='learn';save();home();toast('仅从已加入学习的收藏中取新词；保存中的轮次保持原样。');});renderRows();
  }
  function renderRows(){
    const s=getState(),kind=s.libraryTab,f=filters[kind],q=f.q.trim().toLowerCase();
    let items=kind==='words'?s.notebook.map(id=>words[id]):s.phrases.filter(p=>p.saved);
    items=items.filter(w=>`${w.word||w.text} ${w.meaning}`.toLowerCase().includes(q)).filter(w=>f.status==='all'||(f.status==='unjoined'&&!(kind==='words'?enrolled(w.id):w.enrolled))||(f.status==='joined'&&(kind==='words'?enrolled(w.id):w.enrolled))||(f.status==='exempt'&&s.exempt[w.id]));
    $('#library-list').innerHTML=`<div class="library-count">${items.length} ${kind==='words'?'个单词':'个词组'}<span>收藏不会自动加入学习</span></div>`+(items.length?items.map(w=>kind==='words'?`<article class="library-row"><div class="library-word"><button data-detail-word="${w.id}">${esc(w.word)}</button><span class="library-ipa">/${esc(w.ipa)}/</span><p>${esc(w.pos)} ${esc(w.meaning)}</p><small>${(s.wordSources[w.id]||[]).length} 个演示来源 · ${wordStatus(w.id)}</small></div><div class="library-row-actions"><button class="secondary" data-join-word="${w.id}" ${enrolled(w.id)?'disabled':''}>${enrolled(w.id)?'已加入学习':'加入学习'}</button><button class="text-button" data-source-word="${w.id}">详情与来源 ↗</button><button class="text-button subdued" data-remove-word="${w.id}">取消收藏</button></div></article>`:`<article class="library-row phrase-row"><div class="library-word"><button data-detail-phrase="${w.id}">${esc(w.text)}</button><p>${esc(w.meaning)}</p><small>${w.enrolled?'已加入词组学习':'未加入学习'}${w.due?` · ${w.due<=Date.now()?'已到期':'已安排下次练习'}`:''}</small></div><div class="library-row-actions"><button class="secondary" data-join-phrase="${w.id}" ${w.enrolled?'disabled':''}>${w.enrolled?'已加入学习':'加入学习'}</button>${w.enrolled?`<button class="secondary" data-practice-phrase="${w.id}">${s.phraseRound?.id===w.id&&s.phraseRound.phase!=='DONE'?'继续练习':'练习'}</button>`:''}<button class="text-button" data-source-phrase="${w.id}">详情与来源 ↗</button><button class="text-button subdued" data-remove-phrase="${w.id}">取消收藏</button></div></article>`).join(''):'<div class="library-empty"><h3>这里还没有匹配的收藏</h3><p>试试其他搜索词或筛选条件，也可以在学习时收藏。</p></div>');
    document.querySelectorAll('[data-detail-word],[data-source-word]').forEach(b=>b.onclick=()=>openWord(b.dataset.detailWord||b.dataset.sourceWord,b));
    document.querySelectorAll('[data-detail-phrase],[data-source-phrase]').forEach(b=>b.onclick=()=>openPhrase(b.dataset.detailPhrase||b.dataset.sourcePhrase,b));
    document.querySelectorAll('[data-join-word]').forEach(b=>b.onclick=()=>{const id=b.dataset.joinWord;if(!s.enrolled.includes(id))s.enrolled.push(id);save();renderRows();toast('已加入学习，原有复习状态保持不变。');});
    document.querySelectorAll('[data-remove-word]').forEach(b=>b.onclick=()=>{const id=b.dataset.removeWord;s.notebook.splice(s.notebook.indexOf(id),1);save();renderRows();updateCounts();toast('已取消收藏；学习记录与来源保留。可再次收藏恢复。');});
    document.querySelectorAll('[data-join-phrase]').forEach(b=>b.onclick=()=>{s.phrases.find(p=>p.id===b.dataset.joinPhrase).enrolled=true;save();renderRows();toast('已加入词组学习，不占用单词新学额度。');});
    document.querySelectorAll('[data-practice-phrase]').forEach(b=>b.onclick=()=>openPractice(b.dataset.practicePhrase));
    document.querySelectorAll('[data-remove-phrase]').forEach(b=>b.onclick=()=>{s.phrases.find(p=>p.id===b.dataset.removePhrase).saved=false;save();renderRows();updateCounts();toast('已取消收藏，词组学习记录与来源保留。');});
  }
  function updateCounts(){const s=getState();$('[data-tab="words"] small').textContent=s.notebook.length;$('[data-tab="phrases"] small').textContent=s.phrases.filter(p=>p.saved).length;}
  function sourcesMarkup(sources){return `<section class="drawer-sources"><h3>收藏来源</h3>${sources.length?sources.map(source=>`<article><small>${esc(source.label)}</small>${source.sentence?`<p lang="en">${esc(source.sentence)}</p><p class="muted">${esc(source.translation||'')}</p>`:''}</article>`).join(''):'<p class="muted">来自学习中的收藏，没有文章定位信息。</p>'}<p class="tiny muted">此处仅演示来源展示。正式版保留文章版本和原选区定位；没有真实文章时不生成跳转。</p></section>`;}
  function showDrawer(content,trigger){drawerReturn=trigger;$('#drawer-body').innerHTML=content;$('#library-drawer').showModal();}
  function openWord(id,trigger){const s=getState(),w=words[id];showDrawer(`<p class="tiny muted">生词本 / 词条详情</p><h2 id="drawer-title">${esc(w.word)}</h2><p class="library-ipa">/${esc(w.ipa)}/</p><div class="drawer-status">${wordStatus(id)}</div><div class="drawer-management"><button class="secondary" id="drawer-join" ${enrolled(id)?'disabled':''}>${enrolled(id)?'已加入学习':'加入学习'}</button><button class="secondary" id="drawer-exempt">${s.exempt[id]?'恢复复习':'标记熟练 · 免复习'}</button></div>${details(w)}${sourcesMarkup(s.wordSources[id]||[])}`,trigger);
    $('#drawer-join').onclick=()=>{if(!s.enrolled.includes(id))s.enrolled.push(id);save();$('#drawer-join').textContent='已加入学习';$('#drawer-join').disabled=true;$('.drawer-status').textContent=wordStatus(id);renderRows();};
    $('#drawer-exempt').onclick=()=>{if(s.exempt[id])delete s.exempt[id];else s.exempt[id]={since:Date.now()};save();$('#drawer-exempt').textContent=s.exempt[id]?'恢复复习':'标记熟练 · 免复习';$('.drawer-status').textContent=wordStatus(id);renderRows();toast(s.exempt[id]?'已免复习；未改写保存轮次，返回时跳过此词。':'已恢复原学习安排。');};
  }
  function openPhrase(id,trigger){const p=getState().phrases.find(p=>p.id===id);showDrawer(`<p class="tiny muted">词组本 / 固定搭配</p><h2 id="drawer-title">${esc(p.text)}</h2><p class="phrase-meaning">${esc(p.meaning)}</p><p class="tiny muted">${p.sources[0]?.label?.startsWith('原创')?'原创演示资料':'个人填写释义，未作词典认证'}</p><div class="drawer-management"><button class="secondary" id="edit-phrase">编辑个人释义</button>${p.enrolled?'<button class="primary" id="drawer-practice">词组练习 →</button>':''}</div>${p.note?`<section><h3>个人备注</h3><p>${esc(p.note)}</p></section>`:''}${sourcesMarkup(p.sources)}`,trigger);$('#edit-phrase').onclick=()=>{$('#library-drawer').close();openEditor(id);};$('#drawer-practice')?.addEventListener('click',()=>{$('#library-drawer').close();openPractice(id);});}
  function openEditor(id=null){editId=id;const p=getState().phrases.find(p=>p.id===id);$('#phrase-editor-title').textContent=p?'编辑个人释义':'收藏一个词组';$('#phrase-text').value=p?.text||'';$('#phrase-text').readOnly=!!p;$('#phrase-meaning').value=p?.meaning||'';$('#phrase-note').value=p?.note||'';$('#phrase-editor-error').textContent='';$('#phrase-editor').showModal();}
  function savePhrase(event){event.preventDefault();const s=getState(),text=normalize($('#phrase-text').value),meaning=$('#phrase-meaning').value.trim(),note=$('#phrase-note').value.trim();if(!/^[a-z]+(?:['-][a-z]+)*(?: [a-z]+(?:['-][a-z]+)*){1,9}$/.test(text)||text.length>80||!meaning||meaning.length>300||note.length>500){$('#phrase-editor-error').textContent='请输入2—10个英文单词的词组及中文释义（最多300字），备注最多500字。';return;}
    const old=s.phrases.find(p=>normalize(p.text)===text);if(editId){const p=s.phrases.find(p=>p.id===editId);p.meaning=meaning;p.note=note;}else if(old){old.saved=true;}else{s.phrases.push({id:crypto.randomUUID(),text,meaning,note,saved:true,enrolled:false,sources:[{label:'手动收藏 · 个人输入',sentence:'',translation:''}]});}save();$('#phrase-editor').close();home();toast(old&&!editId?'已在词组本中，原释义和来源保留。':'词组已保存，仅保存在此原型。');}
  function openPractice(id){const s=getState();if(s.phraseRound&&s.phraseRound.phase!=='DONE'&&s.phraseRound.id!==id){toast('还有一个词组练习未完成，先继续它。');return;}if(!s.phraseRound||s.phraseRound.phase==='DONE'){s.phraseRound={id,phase:'MODE',mode:null,failed:false,hinted:false,prefix:''};save();}renderPractice();$('#phrase-practice').showModal();}
  function renderPractice(){const s=getState(),r=s.phraseRound,p=s.phrases.find(p=>p.id===r.id);let body='';
    if(r.phase==='MODE')body=`<h3>这次怎样练习？</h3><p class="muted">单个词组演示，不改变单词轮次与统计。</p><div class="mode-options"><button id="phrase-mode-see">看词组回想含义</button><button id="phrase-mode-write">根据中文默写</button></div>`;
    if(r.phase==='QUESTION')body=r.mode==='SEE'?`<h2 class="phrase-target">${esc(p.text)}</h2><p class="muted">先回想意思，再查看。</p><button class="primary" id="phrase-reveal">查看释义</button>`:`<p class="phrase-meaning">${esc(p.meaning)}</p><label class="field">输入完整词组<input id="phrase-answer" type="text" autocomplete="off" spellcheck="false" value="${esc(r.prefix)}"></label><p class="muted" id="phrase-feedback">${r.hinted?'已提示第一个词，本轮保留辅助记录。':''}</p><div class="drawer-management"><button class="secondary" id="phrase-hint">提示第一个词</button><button class="primary" id="phrase-check">核对</button></div>`;
    if(r.phase==='DETAIL')body=`<h2 class="phrase-target">${esc(p.text)}</h2><p class="phrase-meaning">${esc(p.meaning)}</p><p class="muted">${r.mode==='WRITE'?'本次有错误或辅助，请再默写一次。':'看词自评不计作独立默写。'}</p>${sourcesMarkup(p.sources)}<button class="primary" id="phrase-continue">${r.mode==='WRITE'?'再试一次':'完成这次练习'}</button>`;
    if(r.phase==='DONE')body=`<div class="phrase-success">✓</div><h3>本次词组练习完成</h3><h2 class="phrase-target">${esc(p.text)}</h2><p>${esc(p.meaning)}</p><p class="muted">${r.mode==='WRITE'&&!r.failed?'独立默写通过':'已保留本轮自评或辅助记录'} · 下次 ${p.stage===1?'1':'3'} 天后练习</p><p class="tiny muted">这是词组记录，不增加单词新学或复习次数。</p>`;
    $('#phrase-practice-body').innerHTML=body;
    for(const [selector,mode] of [['#phrase-mode-see','SEE'],['#phrase-mode-write','WRITE']])$(selector)?.addEventListener('click',()=>{r.mode=mode;r.phase='QUESTION';save();renderPractice();});
    $('#phrase-answer')?.addEventListener('input',e=>{r.prefix=e.target.value;save();});
    $('#phrase-answer')?.addEventListener('paste',()=>{r.failed=true;r.hinted=true;save();});
    $('#phrase-hint')?.addEventListener('click',()=>{r.hinted=true;r.failed=true;r.prefix=p.text.split(' ')[0]+' ';save();renderPractice();$('#phrase-answer').focus();});
    $('#phrase-check')?.addEventListener('click',()=>{if(normalize(r.prefix)!==normalize(p.text)){r.failed=true;r.phase='DETAIL';}else if(r.hinted){r.failed=true;r.phase='DETAIL';}else{completePhrase();return;}save();renderPractice();});
    $('#phrase-reveal')?.addEventListener('click',()=>{r.phase='DETAIL';save();renderPractice();});
    $('#phrase-continue')?.addEventListener('click',()=>{if(r.mode==='SEE')completePhrase();else{r.phase='QUESTION';r.hinted=false;r.prefix='';save();renderPractice();}});
  }
  function completePhrase(){const s=getState(),r=s.phraseRound;if(r.phase==='DONE')return;const p=s.phrases.find(p=>p.id===r.id);p.stage=r.failed?1:Math.min(2,(p.stage||0)+1);p.due=Date.now()+(p.stage===1?1:3)*86400000;s.phraseEvents.push({id:p.id,time:Date.now(),independent:r.mode==='WRITE'&&!r.failed,assisted:r.failed});r.phase='DONE';save();renderPractice();renderRows();}
  $('#phrase-editor-form').onsubmit=savePhrase;
  $('#phrase-practice').addEventListener('close',()=>{if(getState().libraryTab==='phrases')render();});
  $('#library-drawer').addEventListener('close',()=>{const id=drawerReturn?.dataset.detailWord||drawerReturn?.dataset.sourceWord,phraseId=drawerReturn?.dataset.detailPhrase||drawerReturn?.dataset.sourcePhrase;const target=drawerReturn?.isConnected?drawerReturn:id?document.querySelector(`[data-detail-word="${id}"]`):phraseId?document.querySelector(`[data-detail-phrase="${phraseId}"]`):null;target?.focus({preventScroll:true});});
  return {ensureState,frame,bindTabs,render,enrolled};
};
